	/** The currently equipped tool. */
	UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category = "Zoo|Tools", meta = (AllowPrivateAccess = "true"))
	EZooTool ActiveTool;

	/** Ordered list of tools for cycling. */
	static const TArray<EZooTool>& GetToolOrder();
};

